cd /tmp/rachel-conv && git fetch origin 2>&1 | grep -c 'friend/' ; python3 - <<'PY'
import subprocess, re, collections
def sh(*a): return subprocess.run(a, capture_output=True, text=True, cwd='/tmp/rachel-conv').stdout
branches = ['rachel','monica','phoebe','joey','chandler','ross']
msgs = {}
for b in branches:
    out = sh('git','log','--format=%H%x00%B%x00---END---','origin/friend/'+b)
    for rec in out.split('\x00---END---\x00'):
        rec = rec.strip('\x00\n')
        if not rec: continue
        sha, body = rec.split('\x00',1)
        if 'Friend-Message: 1' in body:
            msgs[sha.strip()] = (b, body)
print('total friend messages across branches:', len(msgs))
# collect sources from main
files = sh('git','ls-tree','-r','--name-only','origin/main').split('\n')
srcs = set()
for f in files:
    if re.match(r'^S\d\d/E\d\d\.md$', f):
        for line in sh('git','show','origin/main:'+f).split('\n'):
            m = re.match(r'^Source: (friend/\w+) @ ([0-9a-f]{40})', line)
            if m: srcs.add(m.group(2))
print('published sources:', len(srcs))
missing = [s for s in msgs if s not in srcs]
print('missing from transcript:', len(missing))
for m in missing:
    b, body = msgs[m]
    ep = re.search(r'^Episode: (.*)$', body, re.M)
    print(' ', b, m[:10], ep.group(1) if ep else '?', body.split('\n')[-1][:70])
